import sys

def print_digit(num):
    if num == 1:
        print("1")
    else:
        print(f"0")

def main():
    if len(sys.argv) < 2:
        print("Usage: python program.py <number>")
        sys.exit(1)

    num = int(sys.argv[1])
    print_digit(num)

if __name__ == "__main__":
    main()

